import{_ as o,o as a,c as l,a2 as t}from"./chunks/framework.CTeY_0bQ.js";const p=JSON.parse('{"title":"更新记录","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function d(s,e,c,r,n,h){return a(),l("div",null,[...e[0]||(e[0]=[t('<div><h1 id="更新记录" tabindex="-1">更新记录 <a class="header-anchor" href="#更新记录" aria-label="Permalink to &quot;更新记录&quot;">​</a></h1><p>laoshi 的版本号遵循语义化版本，从 0.1.0 开始；每一版的标题写成 <code>## &lt;版本&gt; - &lt;日期&gt;</code>。每一版先写使用者会看到的变化，再写升级须知。laoshi 之前的历史见 paseo-req-kit 的更新记录（laoshi 从它的 1.15.0 抽出）。</p><h2 id="_0-2-0-beta-3-2026-11-11" tabindex="-1">0.2.0-beta.3 - 2026-11-11 <a class="header-anchor" href="#_0-2-0-beta-3-2026-11-11" aria-label="Permalink to &quot;0.2.0-beta.3 - 2026-11-11&quot;">​</a></h2><p>预发布版（npm 的 <code>beta</code> 标签，<code>latest</code> 仍是 0.1.1）：摸高的回调按平台文档的格式解析，步骤做完后靠 <code>done</code> 及时进入下一步，工具调用和用量能收到。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>摸高：回调按平台文档的格式解析</strong>：工具调用（包在 <code>progress</code> 事件里）现在收得到，危险命令拦截和&quot;最近活动&quot;在摸高上开始生效；用量从 <code>usage</code> 字段读并计入缓存命中；<code>error</code> 回调也表示运行结束；上一版启动、这一版接着等的步骤也能靠 <code>done</code> 及时结束。</li></ul><h3 id="升级须知" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li>摸高：专家包要换成这个版本生成的（入口 skill 里写着要装的版本），第一次使用时会装上 0.2.0-beta.3；用 <code>node -p &quot;require(&#39;/data/workspace/.laoshi/npm/node_modules/@yiyi_zhang/laoshi/package.json&#39;).version&quot;</code> 确认。</li></ul><h2 id="_0-2-0-beta-2-2026-11-10" tabindex="-1">0.2.0-beta.2 - 2026-11-10 <a class="header-anchor" href="#_0-2-0-beta-2-2026-11-10" aria-label="Permalink to &quot;0.2.0-beta.2 - 2026-11-10&quot;">​</a></h2><p>预发布版（npm 的 <code>beta</code> 标签，<code>latest</code> 仍是 0.1.1）：修复摸高上步骤做完要等很久才进入下一步的问题；新增不需要平台的命令行 agent 适配器、<code>laoshi migrate</code> 和随 laoshi 发布的 Paseo 需求插件。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化-1" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-1" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>发起人</strong>：状态文件和 <code>laoshi api list</code> 记下每个需求的发起人（<code>startedBy</code>，第一次运行时为谁运行，之后不改）。</li><li><strong>使用者取平台给的身份</strong>：平台提供使用者时（摸高的 <code>AIMAX_USER_NAME</code>）优先用它，<code>LAOSHI_USER</code> 仍然最优先；<code>laoshi doctor</code> 显示使用者从哪里来。</li><li><strong>安装</strong>：程序装在安装根的 <code>npm</code> 目录里时（摸高专家就这样安装），不再提示&quot;需要设置环境变量 LAOSHI_HOME&quot;。</li><li><strong>命令行 agent（不需要平台）</strong>（<code>laoshi install --platform cli</code>）：步骤 agent 是 Claude Code（<code>claude -p</code>）或 Codex（<code>codex exec</code>）的一次运行，追问和打断用会话续接，工具调用来自命令行的事件流（危险命令拦截照常工作）；进展用 <code>laoshi status</code> 查看。第一版，真实命令行上的验证待做。</li><li><strong>摸高：步骤做完后马上进入下一步</strong>：agent 做完但 <code>aimax run</code> 进程不退出时，以完整的输出或平台回调的 <code>done</code> 为准结束这一步，并结束残留的进程（之前要等到平台结束后台命令、再继续时才进入下一步）。</li><li><strong>Paseo 的需求插件随 laoshi 发布</strong>：<code>laoshi plugin install|status|remove</code>（从 paseo-req-kit 迁入，插件 id 改为 <code>laoshi</code>）；安装、升级时顺带更新插件。</li><li><strong><code>laoshi migrate</code></strong>：从 paseo-req-kit 1.x 迁移本机的配置、使用记录、需求索引和需求状态；默认只预览，<code>--apply</code> 执行，<code>--rollback</code> 回滚；旧目录不动。</li><li><strong>文档</strong>：新增《在摸高上使用》《只用命令行 agent》。</li></ul><h3 id="升级须知-1" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-1" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li>摸高：专家包要按这个版本重新生成（<code>node adapters/mogao/make-expert.mjs</code>），入口 skill 第一次使用时会换上这个版本。</li><li>Paseo：装过 paseo-req-kit 插件的，可以改装 laoshi 插件（<code>laoshi plugin install</code>），确认可用后用 <code>req plugin remove</code> 移除旧的。</li></ul><h2 id="_0-2-0-beta-1-2026-11-07" tabindex="-1">0.2.0-beta.1 - 2026-11-07 <a class="header-anchor" href="#_0-2-0-beta-1-2026-11-07" aria-label="Permalink to &quot;0.2.0-beta.1 - 2026-11-07&quot;">​</a></h2><p>预发布版（npm 的 <code>beta</code> 标签，<code>latest</code> 仍是 0.1.1）：支持摸高，用来在摸高沙箱里验证专家。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化-2" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-2" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>支持摸高</strong>（<code>laoshi install --platform mogao</code>）：每一步是摸高的一个独立 agent（<code>aimax run</code>），审批用摸高的人工审批，工具调用和用量来自摸高的进度回调。引擎在对话的命令里运行，进展显示在命令输出里；对话轮次结束打断的运行，下一轮用继续命令接着做。</li><li><strong>摸高专家</strong>：<code>node adapters/mogao/make-expert.mjs</code> 生成提交给摸高的专家（按摸高渲染的 skill 和介绍）；入口 skill 第一次使用时把 laoshi 装到工作区，并说明在摸高上命令会一直运行到停下、等待批准怎么回答、工具装在工作区。</li><li><strong>安装根</strong>：没有 <code>LAOSHI_HOME</code> 时，程序装在 <code>&lt;安装根&gt;/npm</code> 下就用这个安装根（每个对话轮次换机器的平台上不能依赖 <code>~</code>）。</li><li><strong><code>laoshi permission &lt;需求&gt; approve|deny [理由]</code></strong>：在对话里批准或拒绝步骤等待批准的操作，并接着运行（摸高上用）。</li><li><strong>危险命令拦截</strong>：读出凭据环境变量（如 <code>echo $XXX_TOKEN</code>、<code>printenv</code>）算作危险操作。</li></ul><h2 id="_0-1-1-2026-11-05" tabindex="-1">0.1.1 - 2026-11-05 <a class="header-anchor" href="#_0-1-1-2026-11-05" aria-label="Permalink to &quot;0.1.1 - 2026-11-05&quot;">​</a></h2><p>在 npm 上的包名改为 <strong><code>@yiyi_zhang/laoshi</code></strong>：<code>laoshi</code> 这个名字在 npm 上不能使用，0.1.0 只发布到了 GitHub Release，没有发布到 npm。其余内容与 0.1.0 相同。</p><h3 id="升级须知-2" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-2" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li>安装命令：<code>npx -y @yiyi_zhang/laoshi@latest install --platform dsh|paseo</code>（内网加 <code>--registry=&lt;镜像地址&gt;</code>）。装好后的命令仍是 <code>laoshi</code>（别名 <code>req</code>），skill 仍是 <code>/laoshi</code> 等。</li><li>公司的 npm 镜像需要能同步 <code>@yiyi_zhang</code> 作用域下的包。</li><li>用 GitHub Release 上 0.1.0 的 <code>.tgz</code> 或离线包装过的机器，运行一次上面的安装命令即可换成 npm 上的版本。</li></ul><h2 id="_0-1-0-2026-11-05" tabindex="-1">0.1.0 - 2026-11-05 <a class="header-anchor" href="#_0-1-0-2026-11-05" aria-label="Permalink to &quot;0.1.0 - 2026-11-05&quot;">​</a></h2><p>第一个正式版：paseo-req-kit 的需求开发体系，抽成不绑定平台的工具包，支持 Paseo 和 DeepSeek Harness。</p><h3 id="使用者会看到的变化-3" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-3" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>新的名字和命令</strong>：对话中的入口是 <code>/laoshi</code>、<code>/laoshi-setup</code>、<code>/laoshi-doctor</code>、<code>/laoshi-retro</code>；终端命令是 <code>laoshi</code>（<code>req</code> 是它的别名）。</li><li><strong>支持 DeepSeek Harness（dsh）</strong>：步骤 agent 作为子会话挂在发起的对话下，进展和结果发回对话；各角色可以各用一个 dsh 中的模型（<code>&lt;提供方&gt;/&lt;模型&gt;</code>，<code>dsh/chat-model</code> 用对话的模型）；<code>laoshi doctor</code> 列出可用的模型并逐个角色检查。</li><li><strong>内置工作区和服务</strong>：平台不提供时，laoshi 用 <code>git worktree</code> 为需求新建工作区，并按 <code>.laoshi/services.json</code> 启动、检查、停止项目的服务（每个工作区独立端口）。</li><li><strong>一步安装</strong>：<code>npx -y @yiyi_zhang/laoshi@latest install --platform dsh|paseo</code>；公司内网加 <code>--registry=&lt;镜像地址&gt;</code>；<code>laoshi upgrade</code> 升级或回退；<code>laoshi install --check</code>、<code>--uninstall</code>。Windows 上只用 cmd 和 Git Bash。</li><li><strong>离线安装包</strong>：完全没有 npm 源的机器，用 GitHub Release 上带 Windows 依赖的离线安装包，步骤见&quot;内网安装与验证&quot;。</li><li><strong>文档站点</strong>：<a href="https://yiyisf.github.io/laoshi/" target="_blank" rel="noreferrer">https://yiyisf.github.io/laoshi/</a> ；<code>laoshi docs</code> 在本机打开和装的版本一致的文档（不需要外网）。</li><li><strong>体检</strong>：<code>laoshi doctor</code> 的&quot;安装&quot;一节检查 skill 是否已是这个版本的，并从 npm 源查询有没有新版本。</li><li><strong>使用记录带上代码库和使用者</strong>：使用记录、通知事件和 <code>laoshi api list</code> 中增加了代码库（目录、远程地址）和使用者（<code>LAOSHI_USER</code> 或安装级配置的 <code>user</code>）。</li></ul><h3 id="升级须知-从-paseo-req-kit" tabindex="-1">升级须知（从 paseo-req-kit） <a class="header-anchor" href="#升级须知-从-paseo-req-kit" aria-label="Permalink to &quot;升级须知（从 paseo-req-kit）&quot;">​</a></h3><ul><li>laoshi 和 paseo-req-kit 可以装在同一台机器上，互不覆盖：安装根是 <code>~/.laoshi</code>（只有 <code>~/.req-kit</code> 时读取它），项目配置是 <code>.laoshi.json</code>（<code>.requirement-pipeline.json</code> 继续被读取）。</li><li>状态文件升到第 2 版：第一次读到旧的状态文件时自动迁移，原文件留作 <code>.bak-v1</code>；正在运行的流水线只在内存中迁移。</li><li>配置中的 <code>paseoProfile</code>、<code>paseoServices</code> 改名为 <code>platformProfile</code>、<code>platformServices</code>，旧名继续有效。</li><li>Paseo 的需求插件暂时仍由 paseo-req-kit 提供，计划在 0.1.0 之后迁入。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/CHANGELOG.md">CHANGELOG.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/CHANGELOG.md">在 GitHub 上编辑</a></p>',2)])])}const u=o(i,[["render",d]]);export{p as __pageData,u as default};
